                    finally

                    {

                        // update UI

                        progressBar.Invoke(() =>

                        {

                            progressBar.Value1++;

                            progressBar.Text = $"Processed {progressBar.Value1} of {jsonFiles.Length}: {Path.GetFileName(jsonPath)}";

                        });

                    }

                }

            });



            progressBar.Text = $"Conversion complete: {jsonFiles.Length} files processed.";

            ToggleUi(true);

        }









    }



