                if (!inCode)
                {
                    current = Regex.Replace(current, @"\[\s*(\$\$.*\$\$)\s*\]", "$1");

                    var m = Regex.Match(current, @"\$\$\s*(.*?)\s*(\[.*\])\s*(.*?)\s*\$\$");
