                        Message = "Update failed"

                    };

                }



                var updatedEntity = await _dbSet.FindAsync(entity.Id);

                if (updatedEntity == null)

                {

                    return new ReturnPackage<TEntity>

                    {

                        IsSuccessful = false,

                        Message = "Entity not found after update"

                    };

                }



                return new ReturnPackage<TEntity>

                {

